package com.utec.tropelcare.service;
import com.utec.tropelcare.dto.*; import com.utec.tropelcare.entity.Sector; import com.utec.tropelcare.exception.*; import com.utec.tropelcare.repository.SectorRepository; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.List;
@Service public class SectorService{private final SectorRepository repo; public SectorService(SectorRepository r){repo=r;} public SectorDto create(SectorRequest r){if(repo.findBySectorCode(r.sectorCode()).isPresent())throw new ConflictException("El sectorCode ya existe"); if(!Setups.CLIMATES.contains(r.climate()))throw new BusinessException("climate inválido");Sector s=new Sector();s.setSectorCode(r.sectorCode());s.setClimate(r.climate());s.setCapacity(r.capacity());s.setCurrentLoad(0);s.setStabilityLevel(100);s.setCreatedAt(Instant.now());return dto(repo.save(s));} public List<SectorDto> all(){return repo.findAll().stream().map(this::dto).toList();} public SectorDto get(Long id){return dto(repo.findById(id).orElseThrow(()->new NotFoundException("No existe un sector con id "+id)));} private SectorDto dto(Sector s){return new SectorDto(s.getId(),s.getSectorCode(),s.getClimate(),s.getCapacity(),s.getCurrentLoad(),s.getStabilityLevel(),s.getCreatedAt());}}
